from wikilib import *

group("Show", "Show")


@page("wiki-scenes.html", "Scenes and transitions", "Szenen und Übergänge")
def _():
    body = SEC(
        P("A scene is a snapshot of the layers: which clip runs where, with which colors, effects and opacity. **+ Save scene** stores the current picture; a click on a scene recalls it, and the change between two scenes is the **transition**: a fade, a wipe, a flash and 12 more.",
          "Eine Szene ist eine Momentaufnahme der Ebenen: welcher Clip wo läuft, mit welchen Farben, Effekten und welcher Deckkraft. **+ Szene speichern** legt das aktuelle Bild ab; ein Klick auf eine Szene ruft sie ab, und der Wechsel zwischen zwei Szenen ist der **Übergang**: eine Blende, ein Wischen, ein Blitz und 12 weitere."),
        GUIDE("scenes-transition-guide.png", "Scene panel with the transition bar and a fade running", "Szenen-Panel mit der Übergangs-Leiste und laufender Blende", [
            ("**Transition type** for all scenes without their own transition.", "**Übergangsart** für alle Szenen ohne eigenen Übergang."),
            ("**Length**: quick buttons ✂ (cut), 1, 2, 4, 8, or type any number (¼ steps, up to 600); next to it the unit, beats or seconds.", "**Dauer**: Schnellknöpfe ✂ (Schnitt), 1, 2, 4, 8 oder eine beliebige Zahl eintippen (¼-Schritte, bis 600); daneben die Einheit, Beats oder Sekunden."),
            ("**for all scenes**: this setting also replaces the scenes' own transitions.", "**für alle Szenen**: diese Einstellung ersetzt auch die eigenen Übergänge der Szenen."),
            ("**Own transition** of a scene, e.g. 2♩ ◯ = 2 beats circle, ✂ = cut. Crossed out while “for all scenes” is on.", "**Eigener Übergang** einer Szene, z. B. 2♩ ◯ = 2 Beats Kreis, ✂ = Schnitt. Durchgestrichen, solange „für alle Szenen“ an ist."),
            ("The **active scene** (white); the pink bar at the bottom shows the progress of the fade.", "Die **aktive Szene** (weiß); der pinke Balken unten zeigt den Fortschritt der Blende."),
            ("**Pencil**: edit the scene (name, own transition, what comes afterwards).", "**Stift**: Szene bearbeiten (Name, eigener Übergang, was danach kommt)."),
        ]),
        H2("The 15 transitions", "Die 15 Übergänge"),
        IMG("transitions.png", "All 15 transitions, each in the middle of a change from Pop Drop to Warehouse", "Alle 15 Übergänge, jeweils mitten im Wechsel von Pop Drop zu Warehouse",
            ("Every transition at half time, between two scenes of the demo.", "Jeder Übergang zur Hälfte, zwischen zwei Szenen der Demo.")),
        TABLE([("No.", "Nr."), ("Transition", "Übergang"), ("What you see", "Was man sieht"), ("Sign", "Zeichen")], [
            ["1", ("Crossfade", "Überblenden"), ("the old picture fades into the new one", "das alte Bild blendet ins neue über"), "–"],
            ["2", ("Through black", "Über Schwarz"), ("first to black, then up into the new scene", "erst auf Schwarz, dann in die neue Szene auf"), "◼"],
            ["3", ("Through white", "Über Weiß"), ("first to white, then down into the new scene", "erst auf Weiß, dann in die neue Szene ab"), "◻"],
            ["4", ("White flash", "Weißer Blitz"), ("a short white flash, the new scene appears out of it", "ein kurzer weißer Blitz, aus dem die neue Szene auftaucht"), "✦"],
            ["5–8", ("Wipe right, left, up, down", "Wischen nach rechts, links, oben, unten"), ("a soft edge pushes across the picture", "eine weiche Kante wandert über das Bild"), "→ ← ↑ ↓"],
            ["9–10", ("Push left, up", "Schieben nach links, oben"), ("the new picture pushes the old one out", "das neue Bild schiebt das alte hinaus"), "⇠ ⇡"],
            ["11", ("Circle", "Kreis"), ("a circle opens from the middle", "ein Kreis öffnet sich aus der Mitte"), "◯"],
            ["12", ("Zoom", "Zoom"), ("flies into the old picture, the new one settles", "fliegt ins alte Bild, das neue setzt sich"), "⊕"],
            ["13", ("Pixels", "Pixel"), ("the new picture appears pixel block by block", "das neue Bild erscheint Pixelblock für Pixelblock"), "▦"],
            ["14", ("Bright areas first", "Helle Stellen zuerst"), ("the bright parts of the new scene come first", "die hellen Teile der neuen Szene kommen zuerst"), "☀"],
            ["15", ("Glitch", "Glitch"), ("torn stripes with color shift", "zerrissene Streifen mit Farbversatz"), "≋"],
        ]),
        H2("Length: beats or seconds", "Dauer: Beats oder Sekunden"),
        UL(("**Beats**: the transition starts on the next beat and lasts the chosen number of beats (4 beats = one bar). It stays in time when the tempo changes.", "**Beats**: Der Übergang beginnt auf dem nächsten Schlag und dauert die gewählte Zahl Beats (4 Beats = ein Takt). Er bleibt im Takt, wenn sich das Tempo ändert."),
           ("**Seconds**: starts at once and lasts exactly that long, independent of the tempo, good for calm moments.", "**Sekunden**: Beginnt sofort und dauert genau so lange, unabhängig vom Tempo, gut für ruhige Momente."),
           ("**0** or **✂** is a hard cut: the new scene is there at once.", "**0** oder **✂** ist ein harter Schnitt: Die neue Szene ist sofort da.")),
        P("The **Fade** fader in the fader bar (and desk channel 4) sets the same length in seven steps: cut, ¼, ½, 1, 2, 4 and 8 beats (or seconds). Type in the bar for any other value.",
          "Der Regler **Blende** in der Fader-Leiste (und Pult-Kanal 4) stellt dieselbe Dauer in sieben Stufen: Schnitt, ¼, ½, 1, 2, 4 und 8 Beats (bzw. Sekunden). Für andere Werte in der Leiste eintippen."),
        H2("Which transition applies", "Welcher Übergang gilt"),
        DIAGRAM(860, 230, {"rec": (110, 115, 170, 50, "desk", ("Scene recalled", "Szene abgerufen"), None),
                           "q1": (360, 60, 220, 56, "pc", ("“for all scenes” on?", "„für alle Szenen“ an?"), None),
                           "q2": (360, 170, 220, 56, "pc", ("Scene has its own?", "Eigener Übergang?"), None),
                           "bar": (700, 60, 230, 50, "net", ("Transition bar / Fade fader", "Übergangs-Leiste / Blende"), None),
                           "own": (700, 170, 230, 50, "dj", ("The scene's own transition", "Eigener Übergang der Szene"), None)},
                [("rec", "q1", "same", None), ("q1", "bar", "cable", ("yes", "ja")), ("q1", "q2", "same", ("no", "nein")), ("q2", "own", "cable", ("yes", "ja")), ("q2", "bar", "same", ("no", "nein"))],
                cap=("New scenes have no own transition, so the bar and the Fade fader apply to them.", "Neue Szenen haben keinen eigenen Übergang, für sie gelten also Leiste und Regler Blende.")),
        P("The demo and the new project use the bar for most scenes (4 beats crossfade) and give their own transitions only to special moments: a white flash on the pop drop, a circle into the tunnel, glitch for the glitch scene, a cut on the drop.",
          "Demo und neues Projekt nutzen für die meisten Szenen die Leiste (4 Beats Überblenden) und geben nur besonderen Momenten einen eigenen Übergang: einen weißen Blitz beim Pop-Drop, einen Kreis in den Tunnel, Glitch für die Glitch-Szene, einen Schnitt auf dem Drop."),
        H2("Edit a scene", "Eine Szene bearbeiten"),
        GUIDE("scene-edit.png", "Editing a scene", "Eine Szene bearbeiten", [
            ("**Name** of the scene.", "**Name** der Szene."),
            ("**Transition**: like the bar (no own transition), cut, beats or seconds, with the length next to it.", "**Übergang**: wie die Leiste (kein eigener), Schnitt, Beats oder Sekunden, daneben die Dauer."),
            ("**Type** of the own transition (all 15).", "**Art** des eigenen Übergangs (alle 15)."),
            ("**Afterwards**: stays, next after bars, next after seconds, next on a phrase change (LJ-Link).", "**Danach**: bleibt stehen, weiter nach Takten, weiter nach Sekunden, weiter bei Phrasenwechsel (LJ-Link)."),
            ("**Overwrite with the current picture**, move up and down, delete (asks again).", "**Mit aktuellem Bild überschreiben**, nach oben und unten schieben, löschen (fragt nach)."),
        ]),
        P("**Afterwards** only works when **Auto** is on (button at the top, fader bar or desk channel 7). With Auto the scenes run as a show on their own; the demo works like this.",
          "**Danach** wirkt nur, wenn **Auto** an ist (Knopf oben, Fader-Leiste oder Pult-Kanal 7). Mit Auto laufen die Szenen als Show von selbst; die Demo arbeitet so."),
        H2("Recall", "Abrufen"),
        UL(("Scene buttons in the panel and the fader bar, keys 1–9, arrow keys for previous and next.", "Szenen-Tasten im Panel und in der Fader-Leiste, Tasten 1–9, Pfeiltasten für zurück und weiter."),
           ("Desk channel 3 picks the scene, MIDI and OSC (`/vjlink/scene/go`, `/next`, `/prev`) and mapped buttons.", "Pult-Kanal 3 wählt die Szene, dazu MIDI und OSC (`/vjlink/scene/go`, `/next`, `/prev`) und zugewiesene Tasten."),
           ("Transition type, fade length and “for all scenes” can be mapped too (MAPPING: Transition type, Fade, Fade for all scenes).", "Übergangsart, Blende und „für alle Szenen“ lassen sich ebenfalls zuweisen (MAPPING: Übergangsart, Blende, Blende für alle Szenen)."),
           ("Scene cues in SHOW and scene blocks on the timeline.", "Szenen-Cues in der SHOW und Szenen-Blöcke auf der Timeline.")),
        ADM("tip", ("A new recall during a running fade starts the next fade from where the first one was heading, without jumping back.",
                    "Ein neuer Abruf während einer laufenden Blende startet die nächste Blende vom Ziel der ersten aus, ohne Rücksprung.")),
    )
    return (("Scenes with 15 transitions and automatic order", "Szenen mit 15 Übergängen und automatischer Abfolge"),
            ("VJ-Link scenes: 15 transitions (fade, black, white, flash, wipe, push, circle, zoom, pixels, glitch …) in beats or seconds, auto after bars or phrases, recall from desk, MIDI or OSC.",
             "VJ-Link-Szenen: 15 Übergänge (Blende, Schwarz, Weiß, Blitz, Wischen, Schieben, Kreis, Zoom, Pixel, Glitch …) in Beats oder Sekunden, Auto nach Takten oder Phrasen, Abruf vom Pult, per MIDI oder OSC."),
            ("Show", "Show"), ("Scenes and transitions", "Szenen und Übergänge"),
            ("The building blocks of a show.", "Die Bausteine einer Show."), body)


@page("wiki-show.html", "SHOW and timeline", "SHOW und Timeline")
def _():
    body = SEC(
        P("The **SHOW** tab is a running order of cues, like in a theatre: **GO** (space bar) starts the next one, **Back** goes one back, **Stop all** ends everything.",
          "Der Tab **SHOW** ist ein Ablauf aus Cues wie im Theater: **WEITER** (Leertaste) startet den nächsten, **Zurück** geht einen zurück, **Alles stoppen** beendet alles."),
        GUIDE("show-guide.png", "SHOW tab with numbered areas", "SHOW-Tab mit nummerierten Bereichen", [
            ("**Running order**: the cues; a click opens the details, a double click sets the next one.", "**Ablauf**: die Cues; ein Klick öffnet die Details, ein Doppelklick setzt den nächsten."),
            ("**Add cues**: video / image, camera, black, VJ scene, timecode.", "**Cues hinzufügen**: Video / Bild, Kamera, Schwarz, VJ-Szene, Timecode."),
            ("**Timeline** of the selected cue with play, record and the length.", "**Timeline** des gewählten Cues mit Abspielen, Aufnehmen und der Länge."),
            ("**Scene palette**: drag scenes onto the scene track or tap them.", "**Szenen-Palette**: Szenen auf die Szenen-Spur ziehen oder antippen."),
            ("**Effect palette**: strobe, flash, white, W-flash, blinder, blackout onto the effect track.", "**Effekt-Palette**: Strobe, Flash, White, W-Flash, Blinder, Blackout auf die Effekt-Spur."),
            ("**Output preview**.", "**Ausgangs-Vorschau**."),
            ("**GO** starts the next cue (space bar), below Back and Stop all.", "**WEITER** startet den nächsten Cue (Leertaste), darunter Zurück und Alles stoppen."),
            ("**Cue details**: start, wait, duration, end, fades, size.", "**Cue-Details**: Start, Wartezeit, Dauer, Ende, Blenden, Größe."),
        ]),
        H2("Cues", "Cues"),
        TABLE([("Cue", "Cue"), ("What it does", "Was er macht")], [
            [("Video / image", "Video / Bild"), ("plays a file over or instead of the visuals; drag files into the list", "spielt eine Datei über oder statt der Visuals; Dateien einfach in die Liste ziehen")],
            [("Camera", "Kamera"), ("shows a camera input", "zeigt einen Kamera-Eingang")],
            [("Black", "Schwarz"), ("fades the picture to black", "blendet das Bild auf Schwarz")],
            [("VJ scene", "VJ-Szene"), ("recalls a scene", "ruft eine Szene ab")],
            [("Timecode", "Timecode"), ("starts, stops or locates VJ-Link's timecode clock", "startet, stoppt oder springt mit der Timecode-Uhr von VJ-Link")],
        ]),
        H2("Cue details", "Cue-Details"),
        GUIDE("show-cue-guide.png", "Details of the image cue “Logo big”", "Details des Bild-Cues „Logo groß“", [
            ("**Number and name** of the cue.", "**Nummer und Name** des Cues."),
            ("**Start**: by hand (GO), after the previous cue, with the previous cue, or at a timecode.", "**Start**: von Hand (WEITER), nach dem vorigen Cue, mit dem vorigen Cue oder bei einem Timecode."),
            ("**Wait**: seconds between the trigger and the start.", "**Wartezeit**: Sekunden zwischen Auslösen und Start."),
            ("**Duration** of an image or black; 0 = until GO. Videos show start, end and repeat here instead.", "**Dauer** eines Bilds oder von Schwarz; 0 = bis WEITER. Bei Videos stehen hier stattdessen Start, Ende und Wiederholen."),
            ("**At the end**: hold, fade out or go on with the next cue.", "**Am Ende**: stehen bleiben, ausblenden oder mit dem nächsten Cue weiter."),
            ("**Fade in** in seconds.", "**Einblenden** in Sekunden."),
            ("**Fade out** in seconds.", "**Ausblenden** in Sekunden."),
            ("**Size**: fill, fit or original.", "**Größe**: füllen, einpassen oder original."),
            ("**Visuals**: off (only the cue) or over the visuals.", "**Visuals**: aus (nur der Cue) oder über die Visuals legen."),
            ("**Actions**: as next cue, move up and down, convert to timeline, copy, delete.", "**Aktionen**: als Nächstes, nach oben und unten, in Timeline umwandeln, kopieren, löschen."),
        ]),
        DIAGRAM(880, 210, {"go": (90, 105, 130, 50, "desk", ("GO / trigger", "WEITER / Auslöser"), ("by hand, after, with, TC", "Hand, nach, mit, TC")),
                           "w": (270, 105, 120, 44, "tab", ("Wait", "Wartezeit"), None),
                           "fi": (420, 105, 120, 44, "tab", ("Fade in", "Einblenden"), None),
                           "pl": (580, 105, 150, 50, "pc", ("Plays", "Läuft"), ("duration, repeat", "Dauer, Wiederholen")),
                           "end": (780, 105, 150, 50, "net", ("At the end", "Am Ende"), ("hold · fade · go on", "stehen · ausblenden · weiter"))},
                [("go", "w", "same", None), ("w", "fi", "same", None), ("fi", "pl", "same", None), ("pl", "end", "same", None)],
                cap=("The life of a cue. With “go on” the next cue starts by itself; “after previous” and “with previous” chain cues into sequences.",
                     "Der Ablauf eines Cues. Mit „weiter“ startet der nächste Cue von selbst; „nach vorigem“ und „mit vorigem“ verketten Cues zu Abfolgen.")),
        P("Videos also have: trim (start and end), repeat off, x times, until GO or forever, also only a part (loop from/to), and the volume.",
          "Videos haben zusätzlich: kürzen (Start und Ende), wiederholen aus, x-mal, bis WEITER oder endlos, auch nur ein Bereich (Loop von/bis), und die Lautstärke."),
        H2("Timeline", "Timeline"),
        P("**Convert to timeline** (for a video, or an image or black with a duration) opens a big editor under the cue list:", "**In Timeline umwandeln** (bei einem Video oder einem Bild bzw. Schwarz mit Dauer) öffnet einen großen Editor unter der Cue-Liste:"),
        UL(("Drag scenes from the palette onto the track, change the length at the edges, drag the middle to move. Edges snap (⌥ without).", "Szenen aus der Palette auf die Spur ziehen, Länge an den Rändern ziehen, Mitte ziehen verschiebt. Kanten rasten ein (⌥ ohne)."),
           ("Or play the video and tap scenes, or press **Record** and trigger scenes live from pads, keys, MIDI or the desk.", "Oder das Video abspielen und Szenen antippen, oder **Aufnehmen** drücken und Szenen live von Pads, Tasten, MIDI oder Pult auslösen."),
           ("A second track holds effects: strobe, flash, white, W-flash, blinder and blackout.", "Eine zweite Spur hält Effekte: Strobe, Flash, White, W-Flash, Blinder und Blackout."),
           ("In gaps the scene that ran at the start applies. Each block has its own brightness.", "In Lücken gilt die Szene, die beim Start lief. Jeder Block hat eine eigene Helligkeit.")),
    )
    return (("Show running order with timeline and cues", "Show-Ablauf mit Timeline und Cues"),
            ("Run shows with video, image, camera, scene and timecode cues, GO on the space bar and a timeline with scenes, strobe and blackout.",
             "Shows mit Video-, Bild-, Kamera-, Szenen- und Timecode-Cues, WEITER auf der Leertaste und einer Timeline mit Szenen, Strobe und Blackout."),
            ("Show", "Show"), ("SHOW and timeline", "SHOW und Timeline"),
            ("A show with videos and cues, started with GO.", "Eine Show mit Videos und Cues, gestartet mit WEITER."), body)


@page("wiki-timecode.html", "Timecode", "Timecode")
def _():
    body = SEC(
        P("**Settings → Timecode**. Receive and send can be switched on separately, also both at once, over **Art-Net** and **MIDI timecode**, with 24, 25, 29.97 DF and 30 fps.",
          "**Einstellungen → Timecode**. Empfangen und Senden lassen sich getrennt einschalten, auch beides gleichzeitig, über **Art-Net** und **MIDI-Timecode**, mit 24, 25, 29,97 DF und 30 fps."),
        GUIDE("settings-timecode-guide.png", "Timecode settings with receive and send switched on", "Timecode-Einstellungen mit eingeschaltetem Empfangen und Senden", [
            ("**Receive** on/off, below the incoming time and its state.", "**Empfangen** an/aus, darunter die eingehende Zeit und ihr Zustand."),
            ("**Source**: Art-Net or MIDI timecode (MTC).", "**Quelle**: Art-Net oder MIDI-Timecode (MTC)."),
            ("**Videos**: follow the timecode (seek and pause) or are only started.", "**Videos**: folgen dem Timecode (spulen und anhalten) oder werden nur gestartet."),
            ("**On dropout**: run on for 2 s or stop at once.", "**Bei Aussetzer**: 2 s weiterlaufen oder sofort anhalten."),
            ("**Offset**: added to the received time.", "**Versatz**: wird zur empfangenen Zeit addiert."),
            ("**Send** on/off, below the outgoing time.", "**Senden** an/aus, darunter die ausgehende Zeit."),
            ("**What to send**: own clock or pass on the received one.", "**Was senden**: eigene Uhr oder die empfangene weitergeben."),
            ("**Frame rate**: 24, 25, 29.97 DF, 30.", "**Bildrate**: 24, 25, 29,97 DF, 30."),
            ("**Send over**: Art-Net, MIDI or both.", "**Senden über**: Art-Net, MIDI oder beides."),
            ("**Art-Net target**: IP of the desk, or 255.255.255.255 for all.", "**Art-Net-Ziel**: IP des Pults oder 255.255.255.255 für alle."),
            ("**Start time** of the own clock.", "**Startzeit** der eigenen Uhr."),
            ("**Clock**: start, stop, back to the start time.", "**Uhr**: Start, Stopp, zurück auf die Startzeit."),
        ]),
        DIAGRAM(880, 240, {"src": (110, 60, 190, 50, "desk", ("Desk, DAW, player", "Pult, DAW, Player"), ("Art-Net TC or MTC", "Art-Net-TC oder MTC")),
                           "vj": (420, 120, 190, 70, "pc", ("VJ-Link", "VJ-Link"), ("timecode clock", "Timecode-Uhr")),
                           "cues": (110, 180, 190, 50, "tab", ("Cues and videos", "Cues und Videos"), ("start at a time, follow", "Start bei Zeit, folgen")),
                           "ma": (740, 60, 190, 50, "desk", ("grandMA timecode show", "grandMA-Timecode-Show"), None),
                           "own": (740, 180, 190, 50, "tab", ("Timecode cues, mapping", "Timecode-Cues, Mapping"), ("start, stop, locate", "Start, Stopp, Springen"))},
                [("src", "vj", "dmx", ("receive", "empfangen")), ("vj", "cues", "same", None), ("vj", "ma", "cable", ("send", "senden")), ("own", "vj", "same", None)],
                cap=("Receive and send work at the same time: VJ-Link can follow a player and pass the time on to the desk, or run its own clock.",
                     "Empfangen und Senden gehen gleichzeitig: VJ-Link kann einem Player folgen und die Zeit ans Pult weitergeben oder eine eigene Uhr laufen lassen.")),
        H2("Receive", "Empfangen"),
        P("A desk or program sets the time. Cues with the start Timecode follow it, videos follow it (seek and pause), with an offset. If the signal drops out, VJ-Link runs on for 2 s or stops at once.",
          "Ein Pult oder Programm gibt die Zeit vor. Cues mit Start Timecode folgen ihm, Videos folgen (spulen und anhalten), mit Versatz. Fällt das Signal aus, läuft VJ-Link 2 s weiter oder hält sofort an."),
        H2("Send", "Senden"),
        P("VJ-Link sends its own clock or passes on the received one, for example to a grandMA whose timecode show then fires its cues. The clock is controlled by timecode cues in SHOW (start at a time, stop, locate) and by mapping.",
          "VJ-Link sendet seine eigene Uhr oder gibt die empfangene weiter, etwa an einen grandMA, dessen Timecode-Show dann ihre Cues auslöst. Die Uhr steuern Timecode-Cues in der SHOW (Start ab Zeit, Stopp, Springen) und das Mapping."),
        ADM("beta", ("Built and tested with software senders and receivers, not yet with a real desk.", "Gebaut und mit Software-Sendern und -Empfängern getestet, noch nicht mit einem echten Pult.")),
    )
    return (("Timecode: Art-Net and MIDI timecode (MTC)", "Timecode: Art-Net und MIDI-Timecode (MTC)"),
            ("Timecode in VJ-Link: receive Art-Net or MIDI timecode to start cues and follow videos, or send it to a grandMA timecode show.",
             "Timecode in VJ-Link: Art-Net- oder MIDI-Timecode empfangen, um Cues zu starten und Videos folgen zu lassen, oder an eine grandMA-Timecode-Show senden."),
            ("Show", "Show"), ("Timecode", "Timecode"),
            ("Cues and videos in sync with the desk.", "Cues und Videos synchron mit dem Pult."), body)


@page("wiki-projects.html", "Projects", "Projekte")
def _():
    body = SEC(
        P("VJ-Link saves the working state all the time; a crash or a power cut loses nothing. To keep a show or take it to another computer, save it as a **project file**.",
          "VJ-Link sichert den Arbeitsstand laufend; ein Absturz oder Stromausfall verliert nichts. Um eine Show aufzuheben oder auf einen anderen Rechner mitzunehmen, speicherst du sie als **Projektdatei**."),
        UL(("File menu or the project button at the top: New (⌘N), Open (⌘O), Save (⌘S), Save as (⇧⌘S), recently opened.", "Menü Ablage oder der Projektknopf oben: Neu (⌘N), Öffnen (⌘O), Speichern (⌘S), Speichern unter (⇧⌘S), zuletzt geöffnet."),
           ("A `.vjlink` file contains layers, scenes, cues, mappings, outputs and the graphics. Videos go into a folder name Medien next to it; move both together.", "Eine `.vjlink`-Datei enthält Ebenen, Szenen, Cues, Zuweisungen, Ausgänge und die Grafiken. Videos kommen in einen Ordner Name Medien daneben; beides zusammen umziehen."),
           ("A dot next to the name means unsaved changes.", "Ein Punkt neben dem Namen heißt: ungespeicherte Änderungen.")),
        IMG("projects.png", "The project menu at the top left", "Das Projekt-Menü oben links",
            ("The project button opens new, open, save, save as, the start screen and the recently opened projects.", "Der Projektknopf öffnet Neu, Öffnen, Speichern, Speichern unter, den Startbildschirm und die zuletzt geöffneten Projekte.")),
        H2("Start screen and demo", "Startbildschirm und Demo"),
        P("The start screen offers continue, a **new project**, open a file and **Open demo**. A new project is minimal and made for the club: six layers (space, lines, beat, laser, text, logo), black and white with a few strong accents, and eight scenes from calm to drop. The demo is a whole party night for pop house and techno, deliberately over the top: eight layers, 14 scenes from Disco House to Peak Time with their own transitions, full effect stacks, modulations and a timeline show. Take it apart to learn how VJ-Link works.",
          "Der Startbildschirm bietet weiterarbeiten, ein **neues Projekt**, Datei öffnen und **Demo öffnen**. Ein neues Projekt ist minimalistisch und für den Club gemacht: sechs Ebenen (Raum, Linien, Beat, Laser, Text, Logo), Schwarz und Weiß mit wenigen kräftigen Akzenten und acht Szenen von ruhig bis Drop. Die Demo ist eine ganze Partynacht für Pop-House und Techno, bewusst übertrieben: acht Ebenen, 14 Szenen von Disco House bis Peak Time mit eigenen Übergängen, vollen Effekt-Stapeln, Modulationen und einer Timeline-Show. Nimm sie auseinander, um VJ-Link kennenzulernen."),
    )
